import{z as o,x as s,o as A,c as d,q as n,j as i,D as a,d as B,s as l,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"高等教育经济学","description":"","frontmatter":{"title":"高等教育经济学","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-higher-ed.md","filePath":"econ/ed2-higher-ed.md","lastUpdated":1791413859000}'),p={name:"econ/ed2-higher-ed.md"};function c(D,E,C,h,m,u){const r=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=n('<h1 id="高等教育经济学" tabindex="-1">高等教育经济学 <a class="header-anchor" href="#高等教育经济学" aria-label="Permalink to &quot;高等教育经济学&quot;">​</a></h1><div class="epigraph"><p>读大学的账要用整个职业生涯结清，而付学费的账户在十八岁就得开——时点的错配，是高等教育一切政策的起点。</p><footer>—— 据 Card, Econometrica 2001；Dynarski, American Economic Review 2003 整理</footer></div><p><a href="/econ/ed2-school-choice">上一课</a>把基础教育做成市场；高等教育本来就是市场，只是价签更贵、周期更长、贷款约束更紧。基础课已经把回报的两端备齐：<a href="/econ/human-capital-becker">人力资本</a>给了投资框架，<a href="/econ/skill-premium-tinbergen">技能溢价与 Tinbergen 竞赛</a>给了价格。本课把两端接成个体决策，并问三个缺口：平均溢价是不是因果回报、读不完怎么办、钱从哪来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投资口径下，读大学的净现值是溢价的贴现流减去两项成本：学费，以及四年里放弃的收入——后者常被忽略，却往往比学费更贵。<span class="marginnote">数字实例：四年学费 20 万，同期打工每年本可挣 6 万，放弃的收入就是 24 万——机会成本比学费还贵；读大学的「总价」接近 44 万，溢价的贴现流要盖过这个数才划算。</span>溢价本身是均衡价格：\\(w_S/w_U\\) 由相对供给与技能偏向的需求共同决定，扩招会把它压回去，所以「溢价高所以都该读」在加总上不成立。三个缺口由此展开。其一，选择：不读大学的人本来工资轨迹就不同，平均溢价混着能力与志向。其二，完成：学位是期权，读不完退不回成本，完成率才是投资的成败线。其三，流动性：收益挂在二十二岁以后，学费压在十八岁——家庭没有抵押物可借，信贷约束把「值得读」变成「读得起」。<span class="marginnote">术语翻译：信贷约束就是「想借也借不到」——十八岁的学生没有抵押物，市场不愿把钱借给一个四年后才开始回报的计划；于是「值得读」被改写成「读得起」，政策杠杆也因此挂在现金流（助学金）上而不是远期收入上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>因果回报的口径在<a href="/econ/ca-education-causal">教育中的因果问题</a>已经立好：义务教育工具的估计不低于 OLS（Card 2001 的综述），说明被约束的边际学生回报不低于平均——约束长在信贷与信息，不长在能力。但个体决策还要多看两块。选择性溢价：Dale–Krueger 2002 把「申请了哪些学校」当控制集，更精英的母校几乎不再抬高收入——名校溢价里至少有一部分是能力与志向的标签，不是教学的产品。<span class="marginnote">常见误区：「上名校所以收入高」。能考进名校的人本来就带着能力与志向；条件于「申请了哪些学校」，名校标签的收入加成基本消失。把筛选误当生产，是教育回报讨论里最常见的混淆。</span>跳跃的文凭：文凭年（毕业年）的收入跳升即羊皮纸效应（Jaeger–Page 1996 的证据），提示<a href="/econ/signaling-spence-labor">教育作为信号</a>的成分在高等教育不可忽略——完成与肄业在市场眼里是两种商品。价格弹性：Dynarski 2003 的项目证据显示，上千美元的助学金变动能把入学概率挪动好几个百分点——对约束中的家庭，教育需求的收入弹性远高于经济学直觉。</p>',7)),(A(),i(t,null,{default:a(()=>[l(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22%E8%83%BD%E5%8A%9B%E4%B8%8E%E5%BF%97%E5%90%91%22%5D%20--%3E%20AP%5B%22%E7%94%B3%E8%AF%B7%E9%9B%86%E5%90%88%22%5D%0A%20%20AP%20--%3E%20AD%5B%22%E5%BD%95%E5%8F%96%E4%B8%8E%E9%99%A2%E6%A0%A1%E9%80%89%E6%8B%A9%22%5D%0A%20%20AD%20--%3E%20CP%7B%22%E5%AE%8C%E6%88%90%EF%BC%9F%22%7D%0A%20%20CP%20--%3E%7C%E6%AF%95%E4%B8%9A%7C%20PR%5B%22%E5%AD%A6%E4%BD%8D%E6%BA%A2%E4%BB%B7%20%2B%20%E7%BE%8A%E7%9A%AE%E7%BA%B8%E8%B7%B3%E5%8D%87%22%5D%0A%20%20CP%20--%3E%7C%E8%82%84%E4%B8%9A%7C%20NO%5B%22%E9%83%A8%E5%88%86%E5%9B%9E%E6%8A%A5%EF%BC%9A%E6%88%90%E6%9C%AC%E5%B7%B2%E6%B2%89%E6%B2%A1%22%5D%0A%20%20FIN%5B%22%E4%BF%A1%E8%B4%B7%E4%B8%8E%E5%8A%A9%E5%AD%A6%E9%87%91%22%5D%20--%3E%20AP%0A%20%20FIN%20--%3E%20CP%0A%20%20EQ%5B%22%E9%98%9F%E5%88%97%E6%89%A9%E6%8B%9B%22%5D%20-.%E6%BA%A2%E4%BB%B7%E8%A2%AB%E5%8E%8B%E5%9B%9E.-%3E%20PR%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"完成率是被低估的边际：同样是补助，花在「让已入学的人读到毕业」与花在「让边缘的人进门」是两个不同的政策，前者的回报经常更高——肄业者拿走了大部分成本，却拿不到羊皮纸。",-1)),E[5]||(E[5]=e("p",null,"两份同样的补助花在哪个边际，回报路径并不对称。",-1)),(A(),i(t,null,{default:a(()=>[l(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E7%AC%94%E8%A1%A5%E5%8A%A9%22%5D%20--%3E%20A%7B%22%E8%8A%B1%E5%9C%A8%E5%93%AA%E4%B8%AA%E8%BE%B9%E9%99%85%22%7D%0A%20%20A%20--%3E%7C%22%E8%AE%A9%E8%BE%B9%E7%BC%98%E7%9A%84%E4%BA%BA%E8%BF%9B%E9%97%A8%22%7C%20E1%5B%22%E5%85%A5%E5%AD%A6%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20E1%20--%3E%20E2%5B%22%E8%8B%A5%E8%AF%BB%E4%B8%8D%E5%AE%8C%3A%20%E6%88%90%E6%9C%AC%E5%B7%B2%E4%BB%98%2C%20%E7%BE%8A%E7%9A%AE%E7%BA%B8%E6%B2%A1%E6%8B%BF%E5%88%B0%22%5D%0A%20%20A%20--%3E%7C%22%E8%AE%A9%E5%9C%A8%E8%AF%BB%E7%9A%84%E4%BA%BA%E8%AF%BB%E5%88%B0%E6%AF%95%E4%B8%9A%22%7C%20C1%5B%22%E5%AE%8C%E6%88%90%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%96%87%E5%87%AD%E8%B7%B3%E5%8D%87%E8%90%BD%E5%9C%B0%2C%20%E5%9B%9E%E6%8A%A5%E5%85%91%E7%8E%B0%22%5D%0A%20%20E2%20--%3E%20V%5B%22%E5%AE%8C%E6%88%90%E8%BE%B9%E9%99%85%E7%9A%84%E5%9B%9E%E6%8A%A5%E7%BB%8F%E5%B8%B8%E6%9B%B4%E9%AB%98%22%5D%0A%20%20C2%20--%3E%20V%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p>专业与院校构成同样内生于价格：高溢价领域吸纳入学分流，这是竞赛在高教内部的重演。信贷约束的机制是流动性而非终身收入：约束家庭的孩子不是「一辈子挣不回学费」，而是「十八岁拿不出学费」——所以助学金弹性大、而远期补贴弹性小，政策的杠杆挂在现金流上。信号成分则给出社会口径的告诫：如果教育的部分回报是排序，那么全社会一起多读一年书，溢价按竞赛逻辑重新定价，个体回报高估社会回报。</p><p><span class="marginnote">Dale–Krueger 2002 的 matched-applicant 口径：条件于申请集合，母校选择性的收入溢价消失；只在弱势与少数族裔子样本里残余正效应——名校可能是那部分学生获得信息与网络的通道。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>平均溢价是个时点的均衡价格，不能当个人决策的充分统计：它随队列扩招变动，也随技术偏向变动。回报分布右偏而分散，均值掩盖了艺术类、营利部门的大量低回报尾部。Dale–Krueger 的口径控制的是申请行为，控制不掉「被录取后怎么选」，真正的因果关系仍在追赶。最后，本课把四年制本科当标准品；两年制、证书与再培训市场的经济学更接近下一课的终身技能框架——高等教育只是技能形成的一生里最显眼的一段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>投资口径：溢价的贴现流，减学费与放弃的收入；溢价是会被扩招压回的均衡价格。</li><li>边际学生回报不低于平均（Card 2001），约束在信贷与信息，不在能力。</li><li>羊皮纸效应提示信号成分：完成与肄业在市场眼里是两种商品，完成率是政策杠杆。</li><li>Dale–Krueger：条件于申请集合，选择性溢价基本消失；助学金对约束家庭的弹性大。</li><li>出处：Card, Econometrica 2001；Dale and Krueger, QJE 2002；Jaeger and Page, REStat 1996；Dynarski, AER 2003。</li></ul>',6))])}const _=o(p,[["render",c]]);export{g as __pageData,_ as default};
